const inputData = $input.all();
let currentNumber = 100001;

if (inputData.length > 0 && inputData[0].json.number) {
  currentNumber = inputData[0].json.number;
}

console.log(`Processing PDF number: ${currentNumber}`);

return [{
  json: {
    number: currentNumber
  }
}];

const number = $json.number;

// Change the URL to point to PDF files instead of JPG
const url = `http://cr.skyaierp.com/pdf/10-24/${number}.pdf`;

return [{
  json: {
    number: number,
    url: url
  }
}];

const pdfResult = $input.first();

console.log('PDF extraction result:', JSON.stringify(pdfResult, null, 2));

// Extract text from PDF result
let extractedText = '';

if (pdfResult.json && pdfResult.json.text) {
  extractedText = pdfResult.json.text;
} else if (pdfResult.json && typeof pdfResult.json === 'string') {
  extractedText = pdfResult.json;
} else {
  return {
    json: {
      error: true,
      message: 'No text extracted from PDF',
      result: pdfResult
    }
  };
}

// Clean the extracted text
const cleanedText = extractedText
  .replace(/\r\n/g, '\n')
  .replace(/[ \t]{2,}/g, ' ')
  .replace(/\n\s*\n/g, '\n\n')
  .trim();

// Split text into chunks for processing
const chunkSize = 4000;
const chunks = [];

for (let i = 0; i < cleanedText.length; i += chunkSize) {
  chunks.push(cleanedText.slice(i, i + chunkSize));
}

console.log('Extracted text length:', extractedText.length);
console.log('Text preview:', extractedText.substring(0, 300));

return {
  json: {
    originalText: extractedText,
    cleanedText: cleanedText,
    textChunks: chunks,
    success: true,
    textLength: extractedText.length
  }
};

let outputStr = $input.first().json.output;

let jsonMatch = outputStr.match(/({[\s\S]*})/);

if (!jsonMatch) {
  throw new Error("No valid JSON found in AI output!");
}

let data = JSON.parse(jsonMatch[1]);

if (!data.jsonnumber) {
  data.jsonnumber = $('Counter Node').first().json.number;
}

console.log(`Final data for PDF ${data.jsonnumber}:`, JSON.stringify(data, null, 2));

return [{ json: data }];

let current = $('Counter Node').first().json.number;

console.log(`Finished processing PDF number: ${current}`);

if (current >= 100301) {
  console.log('All PDFs processed!');
  return [{
    json: {
      finished: true,
      message: `Completed processing PDFs 1-${current}`,
      totalProcessed: current
    }
  }];
}

let next = current + 1;
console.log(`Next PDF to process: ${next}`);

return [{
  json: {
    number: next,
    continue: true,
    currentlyProcessed: current
  }
}];

let nextNumber = $('Loop Check').first().json.number;

console.log(`Looping back with number: ${nextNumber}`);

return [{
  json: {
    number: nextNumber
  }
}];
